B.acq=new A.bp("D\u1eef li\u1ec7u k\u1ebft n\u1ed1i tr\u1ef1c ti\u1ebfp t\u1eeb m\xe1y ch\u1ee7 Smart Museum Guide System.",B.K,null)
B.acr=new A.bp("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.K,null)
B.act=new A.bp("Nh\u1eadp m\xe3 do ng\u01b0\u1eddi mua g\xf3i nh\xf3m chia s\u1ebb \u0111\u1ec3 nh\u1eadn quy\u1ec1n truy c\u1eadp.",B.K,null)
B.acu=new A.bp("Gi\xe1 v\xe0 th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 x\xe1c nh\u1eadn khi t\u1ea1o \u0111\u01a1n. Quy\u1ec1n truy c\u1eadp ch\u1ec9 \u0111\u01b0\u1ee3c c\u1ea5p sau khi m\xe1y ch\u1ee7 x\xe1c nh\u1eadn thanh to\xe1n.",B.K,null)
B.acv=new A.bp("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng c\xf4ng khai.",B.K,null)
B.acw=new A.bp("\u0110\xe3 ghi nh\u1eadn l\u01b0\u1ee3t qu\xe9t. C\xe2u \u0111\u1ed1 v\xe0 \u0111i\u1ec3m \u0111\u01b0\u1ee3c h\u1ec7 th\u1ed1ng c\u1eadp nh\u1eadt n\u1ebfu \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n.",B.K,null)
B.acx=new A.bp("Gi\u1ecdng \u0111\u1ecdc \u0111\u01b0\u1ee3c t\u1ed5ng h\u1ee3p t\u1ef1 \u0111\u1ed9ng t\u1eeb microservice TTS AI tr\xean n\u1ed9i dung thuy\u1ebft minh \u0111\xe3 \u0111\u01b0\u1ee3c Gi\xe1m tuy\u1ec3n ph\xea duy\u1ec7t.",B.K,null)
B.acy=new A.bp("L\u01b0\u1ee3t tham quan t\u1ef1 do. Qu\xe9t QR t\u1ea1i hi\u1ec7n v\u1eadt \u0111\u1ec3 ghi nh\u1eadn kh\xe1m ph\xe1.",B.K,null)
B.acz=new A.bp("Ch\u01b0a c\xf3 s\u01a1 \u0111\u1ed3 \u0111\u01b0\u1eddng \u0111i \u0111\u01b0\u1ee3c li\xean k\u1ebft v\u1edbi h\xe0nh tr\xecnh n\xe0y. H\xe3y xem bi\u1ec3n ch\u1ec9 d\u1eabn ho\u1eb7c h\u1ecfi nh\xe2n vi\xean b\u1ea3o t\xe0ng.",B.K,null)
B.acA=new A.bp("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.K,null)
B.acB=new A.bp("C\xe2u h\u1ecfi \u0111\u01b0\u1ee3c m\u1edf sau khi h\u1ec7 th\u1ed1ng ghi nh\u1eadn b\u1ea1n qu\xe9t hi\u1ec7n v\u1eadt c\xf3 b\u1ed9 c\xe2u h\u1ecfi \u0111\xe3 xu\u1ea5t b\u1ea3n.",B.K,null)
B.acC=new A.bp("Ch\u01b0a c\xf3 quy\u1ec1n truy c\u1eadp \u0111\u01b0\u1ee3c c\u1ea5p.",B.K,null)
B.acE=new A.bp("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.K,null)
B.acF=new A.bp("Tr\u1ea3i nghi\u1ec7m m\xf4 ph\u1ecfng tr\xean web, kh\xf4ng s\u1eed d\u1ee5ng m\xe1y \u1ea3nh.",B.K,null)
B.acH=new A.bp("\u0110\xe1nh gi\xe1 b\u1ea3o t\xe0ng c\u1ea7n g\u1eafn v\u1edbi l\u01b0\u1ee3t tham quan \u0111\xe3 ho\xe0n th\xe0nh. G\xf3p \xfd chung s\u1ebd \u0111\u01b0\u1ee3c g\u1eedi \u0111\u1ebfn b\u1ed9 ph\u1eadn h\u1ed7 tr\u1ee3.",B.K,null)
B.acI=new A.bp("C\xe1c h\xe0nh tr\xecnh \u0111\u01b0\u1ee3c t\u1ea3i t\u1eeb m\xe1y ch\u1ee7 v\xe0 l\u1ecdc theo th\u1eddi gian. S\u1edf th\xedch ch\u01b0a \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 h\u1ed7 tr\u1ee3 l\u1ecdc.",B.K,null)
B.acJ=new A.bp("B\u1ea1n c\xf3 th\u1ec3 g\u1eedi v\u1ea5n \u0111\u1ec1 v\u1ec1 d\u1ecbch v\u1ee5 ho\u1eb7c \u0111\u01a1n h\xe0ng. Vi\u1ec7c g\u1eedi y\xeau c\u1ea7u kh\xf4ng t\u1ef1 \u0111\u1ed9ng ho\xe0n ti\u1ec1n; h\u1ec7 th\u1ed1ng ch\u01b0a h\u1ed7 tr\u1ee3 ho\xe0n ti\u1ec1n tr\u1ef1c ti\u1ebfp.",B.K,null)
B.acK=new A.bp("B\u1ea1n ch\u01b0a c\xf3 huy hi\u1ec7u.",B.K,null)
B.acL=new A.bp("\u0110\xe1nh gi\xe1 n\xe0y \u0111\xe3 h\u1ebft th\u1eddi h\u1ea1n ch\u1ec9nh s\u1eeda.",B.K,null)
B.acM=new A.bp("Danh s\xe1ch th\u1ec3 hi\u1ec7n th\u1ee9 t\u1ef1 tham quan, kh\xf4ng ph\u1ea3i s\u01a1 \u0111\u1ed3 \u0111\u01b0\u1eddng \u0111i. Ti\u1ebfn \u0111\u1ed9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean hi\u1ec7n t\u1ea1i.",B.K,null)
